import React, { useState } from "react";
import "./App.css";
import { Gamepad2, Globe, ChevronDown, User, LogOut, LayoutDashboard, UserCircle } from 'lucide-react'; 
import { Routes, Route, useNavigate, useLocation } from "react-router-dom";

// Components
import Login from "./Login";
import Signup from "./Signup";
import Dashboard from "./components/Dashboard"; // The Green Banner Dashboard
import Chatbot from "./components/Chatbot";

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false); // Manages login state
  const [showProfileMenu, setShowProfileMenu] = useState(false); // Toggles the dropdown
  
  const navigate = useNavigate();
  const location = useLocation();

  const handleLogout = () => {
     setIsLoggedIn(false);
     setShowProfileMenu(false);
     navigate("/");
  };

  return (
    <div className="app-root">
      
      {/* --- NAVBAR --- */}
      {/* Visible on Home and Dashboard, Hidden on Login/Signup */}
      {!location.pathname.includes("/login") && !location.pathname.includes("/signup") && (
        <nav className="navbar">
           {/* Logo clicks to Home */}
           <div className="logo" onClick={() => navigate("/")}><Gamepad2 size={32} /> VidyaQuest</div>
           
           <div className="nav-links">
              <span onClick={() => navigate("/")}>Home</span>
              <span onClick={() => navigate(isLoggedIn ? "/dashboard" : "/login")}>Subjects</span>
              <span>Games</span>
              <span>Leaderboard</span>
           </div>

           <div className="auth-buttons">
              <button className="btn-secondary">
                 <Globe size={16}/> English
              </button>

              {!isLoggedIn ? (
                 /* STATE 1: NOT LOGGED IN */
                 <>
                    <span style={{fontWeight:'600', cursor:'pointer', marginRight:'10px'}} onClick={() => navigate("/login")}>Sign In</span>
                    <button className="btn-primary" onClick={() => navigate("/signup")}>Sign Up</button>
                 </>
              ) : (
                 /* STATE 2: LOGGED IN (Shows Srija) */
                 <div style={{position:'relative'}}>
                    <button className="btn-user" onClick={() => setShowProfileMenu(!showProfileMenu)}>
                       <User size={18}/> srija <ChevronDown size={14}/>
                    </button>
                    
                    {/* DROPDOWN MENU */}
                    {showProfileMenu && (
                       <div className="profile-menu">
                          <div className="menu-item" onClick={() => {navigate("/dashboard"); setShowProfileMenu(false);}}>
                             <UserCircle size={18}/> Profile
                          </div>
                          <div className="menu-item" onClick={() => {navigate("/dashboard"); setShowProfileMenu(false);}}>
                             <LayoutDashboard size={18}/> Dashboard
                          </div>
                          <div className="menu-item danger" onClick={handleLogout}>
                             <LogOut size={18}/> Sign Out
                          </div>
                       </div>
                    )}
                 </div>
              )}
           </div>
        </nav>
      )}

      {/* --- ROUTES --- */}
      <Routes>
        <Route path="/" element={<LandingPage isLoggedIn={isLoggedIn} navigate={navigate}/>} />
        
        {/* Login: On success, go to HOME (/) but set state to Logged In */}
        <Route path="/login" element={<Login onSuccess={() => { setIsLoggedIn(true); navigate("/"); }} />} />
        
        {/* Signup: On success, go to Login */}
        <Route path="/signup" element={<Signup onSuccess={() => navigate("/login")} />} />
        
        {/* Dashboard: The Green Banner Page */}
        <Route path="/dashboard" element={<Dashboard />} />
      </Routes>

      {/* Chatbot */}
      {!location.pathname.includes("/login") && !location.pathname.includes("/signup") && <Chatbot />}
    </div>
  );
}

// Simple Landing Page Component
function LandingPage({ isLoggedIn, navigate }) {
   return (
      <header className="hero-section">
         <span className="grade-badge">✨ For Grades 6-12</span>
         <h1 className="hero-title">Learn, Play & <br/><span style={{color:'#0d9488'}}>Grow!</span></h1>
         <p style={{fontSize:'1.2rem', color:'#64748b', marginBottom:'2rem'}}>Making STEM education fun and accessible for rural students.</p>
         
         <div style={{display:'flex', justifyContent:'center', gap:'1rem'}}>
            <button className="btn-primary" style={{padding:'12px 30px', fontSize:'1.1rem'}} onClick={() => navigate(isLoggedIn ? "/dashboard" : "/signup")}>
               {isLoggedIn ? "Go to Dashboard" : "✨ Start Learning"}
            </button>
            <button className="btn-secondary" style={{padding:'12px 30px', fontSize:'1.1rem'}}>▶ Watch Demo</button>
         </div>

         <div className="stats-row">
            <div className="stat-card">
               <strong style={{fontSize:'2.5rem', color:'#0d9488', display:'block'}}>10K+</strong>
               <span>Students Learning</span>
            </div>
            <div className="stat-card">
               <strong style={{fontSize:'2.5rem', color:'#f97316', display:'block'}}>500+</strong>
               <span>Lessons Completed</span>
            </div>
            <div className="stat-card">
               <strong style={{fontSize:'2.5rem', color:'#3b82f6', display:'block'}}>1000+</strong>
               <span>Hours of Content</span>
            </div>
         </div>
      </header>
   );
}
